mapper.select:
SELECT id, type, name, sort, status, create_time, update_time, create_user, update_user
FROM category

    name = #{name}
    AND type = #{type}

ORDER BY sort ASC, create_time DESC

mapper.update:
UPDATE category
type = #{type}, name = #{name}, sort = #{sort}, update_time = #{updateTime}, update_user = #{updateUser},
WHERE id = #{id}

